DROP TABLE IF EXISTS `core_permisos_listado`;
CREATE TABLE `core_permisos_listado`  (
  `idAdmpm` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_pmcat` int UNSIGNED NOT NULL,
  `Direccionweb` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Direccionbase` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Nombre` varchar(120) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `visualizacion` int UNSIGNED NOT NULL,
  `Version` decimal(4, 2) UNSIGNED NOT NULL,
  `Descripcion` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Level_Limit` int UNSIGNED NOT NULL,
  `Habilita` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Principal` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`idAdmpm`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 583 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci COMMENT = 'Administrador' ROW_FORMAT = Dynamic;

