DROP TABLE IF EXISTS `cotizacion_listado`;
CREATE TABLE `cotizacion_listado`  (
  `idCotizacion` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `idSistema` int UNSIGNED NOT NULL,
  `idUsuario` int UNSIGNED NOT NULL,
  `idCliente` int UNSIGNED NOT NULL,
  `Creacion_fecha` date NOT NULL,
  `Creacion_mes` int UNSIGNED NOT NULL,
  `Creacion_ano` int UNSIGNED NOT NULL,
  `Observaciones` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ValorNetoImp` int UNSIGNED NOT NULL,
  `Impuesto_01` int UNSIGNED NOT NULL,
  `Impuesto_02` int UNSIGNED NOT NULL,
  `Impuesto_03` int UNSIGNED NOT NULL,
  `Impuesto_04` int UNSIGNED NOT NULL,
  `Impuesto_05` int UNSIGNED NOT NULL,
  `Impuesto_06` int UNSIGNED NOT NULL,
  `Impuesto_07` int UNSIGNED NOT NULL,
  `Impuesto_08` int UNSIGNED NOT NULL,
  `Impuesto_09` int UNSIGNED NOT NULL,
  `Impuesto_10` int UNSIGNED NOT NULL,
  `ValorTotal` int UNSIGNED NOT NULL,
  `fecha_auto` date NOT NULL,
  PRIMARY KEY (`idCotizacion`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci COMMENT = 'Limpiar al entregar' ROW_FORMAT = Dynamic;

