CREATE TABLE `telemetria_carga_bam`  (
  `idCarga` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `idSistema` int UNSIGNED NOT NULL,
  `idTelemetria` int UNSIGNED NOT NULL,
  `idUsuario` int UNSIGNED NOT NULL,
  `FechaCarga` date NOT NULL,
  `FechaVencimiento` date NOT NULL,
  `Ano` int UNSIGNED NOT NULL,
  `Mes` int UNSIGNED NOT NULL,
  `Semana` int UNSIGNED NOT NULL,
  `Dia` int NOT NULL,
  `idDocPago` int UNSIGNED NOT NULL,
